-- Coursemap baseline, part 6 of 8: campus map and indoor maps
--
-- Campuses, map layers, places and the vector features drawn for them, plus
-- the indoor map documents the room finder walks a reader through. A
-- building is extruded from its real footprint, so an indoor map is a
-- document with floors rather than a picture of one.

create table if not exists public.campus_indoor_maps (
    id uuid default gen_random_uuid() not null,
    building_place_id uuid not null,
    name text not null,
    document jsonb not null,
    status text default 'draft'::text not null,
    revision integer default 1 not null,
    source_provider text,
    source_url text,
    source_license text,
    published_at timestamp with time zone,
    created_at timestamp with time zone default now() not null,
    updated_at timestamp with time zone default now() not null,
    constraint campus_indoor_maps_document_check check (((jsonb_typeof(document) = 'object'::text) and ((document ->> 'version'::text) = any (array['1'::text, '2'::text])) and (jsonb_typeof((document -> 'viewBox'::text)) = 'object'::text) and (jsonb_typeof((document -> 'levels'::text)) = 'array'::text) and (jsonb_typeof((document -> 'spaces'::text)) = 'array'::text) and (jsonb_typeof((document -> 'connectors'::text)) = 'array'::text) and (jsonb_typeof((document -> 'routeNodes'::text)) = 'array'::text) and (jsonb_typeof((document -> 'routeEdges'::text)) = 'array'::text) and (((document -> 'walls'::text) is null) or (jsonb_typeof((document -> 'walls'::text)) = 'array'::text)))),
    constraint campus_indoor_maps_name_check check (((btrim(name) <> ''::text) and (char_length(btrim(name)) <= 200))),
    constraint campus_indoor_maps_published_at_check check (((status <> 'published'::text) or (published_at is not null))),
    constraint campus_indoor_maps_revision_check check ((revision > 0)),
    constraint campus_indoor_maps_source_license_not_blank_check check (((source_license is null) or (btrim(source_license) <> ''::text))),
    constraint campus_indoor_maps_source_provider_not_blank_check check (((source_provider is null) or (btrim(source_provider) <> ''::text))),
    constraint campus_indoor_maps_source_url_check check (((source_url is null) or (source_url ~ '^https://'::text))),
    constraint campus_indoor_maps_status_check check ((status = any (array['draft'::text, 'published'::text, 'archived'::text])))
);

create table if not exists public.campus_map_campuses (
    id uuid default gen_random_uuid() not null,
    slug text not null,
    name text not null,
    boundary_geojson jsonb not null,
    west double precision not null,
    south double precision not null,
    east double precision not null,
    north double precision not null,
    initial_longitude double precision not null,
    initial_latitude double precision not null,
    initial_zoom double precision default 18 not null,
    min_zoom double precision default 15 not null,
    max_zoom double precision default 19 not null,
    source_identifier text not null,
    source_url text not null,
    source_license text not null,
    status text default 'draft'::text not null,
    sort_order integer default 0 not null,
    created_at timestamp with time zone default now() not null,
    updated_at timestamp with time zone default now() not null,
    constraint campus_map_campuses_boundary_geojson_check check (((jsonb_typeof(boundary_geojson) = 'object'::text) and ((boundary_geojson ->> 'type'::text) = 'Polygon'::text) and (jsonb_typeof((boundary_geojson -> 'coordinates'::text)) = 'array'::text))),
    constraint campus_map_campuses_bounds_check check ((((west >= ('-180'::integer)::double precision) and (west <= (180)::double precision)) and ((east >= ('-180'::integer)::double precision) and (east <= (180)::double precision)) and ((south >= ('-90'::integer)::double precision) and (south <= (90)::double precision)) and ((north >= ('-90'::integer)::double precision) and (north <= (90)::double precision)) and (west < east) and (south < north))),
    constraint campus_map_campuses_centre_check check ((((initial_longitude >= west) and (initial_longitude <= east)) and ((initial_latitude >= south) and (initial_latitude <= north)))),
    constraint campus_map_campuses_name_not_blank_check check ((btrim(name) <> ''::text)),
    constraint campus_map_campuses_slug_format_check check ((slug ~ '^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$'::text)),
    constraint campus_map_campuses_sort_order_check check ((sort_order >= 0)),
    constraint campus_map_campuses_source_identifier_not_blank_check check ((btrim(source_identifier) <> ''::text)),
    constraint campus_map_campuses_source_license_not_blank_check check ((btrim(source_license) <> ''::text)),
    constraint campus_map_campuses_source_url_check check ((source_url ~ '^https://'::text)),
    constraint campus_map_campuses_status_check check ((status = any (array['draft'::text, 'published'::text, 'archived'::text]))),
    constraint campus_map_campuses_zoom_check check (((min_zoom >= (0)::double precision) and (min_zoom <= initial_zoom) and (initial_zoom <= max_zoom) and (max_zoom <= (24)::double precision)))
);

create table if not exists public.campus_map_features (
    id uuid default gen_random_uuid() not null,
    campus_id uuid not null,
    layer_id uuid not null,
    place_id uuid,
    slug text not null,
    name text not null,
    feature_kind text not null,
    geometry_geojson jsonb not null,
    source_identifier text not null,
    source_url text not null,
    source_license text not null,
    status text default 'draft'::text not null,
    sort_order integer default 0 not null,
    created_at timestamp with time zone default now() not null,
    updated_at timestamp with time zone default now() not null,
    height_metres double precision default 5 not null,
    minimum_height_metres double precision default 0 not null,
    source_properties jsonb default '{}'::jsonb not null,
    constraint campus_map_features_geometry_geojson_check check (((jsonb_typeof(geometry_geojson) = 'object'::text) and ((geometry_geojson ->> 'type'::text) = any (array['Polygon'::text, 'MultiPolygon'::text, 'LineString'::text])) and (jsonb_typeof((geometry_geojson -> 'coordinates'::text)) = 'array'::text) and (((feature_kind = 'building'::text) and ((geometry_geojson ->> 'type'::text) = any (array['Polygon'::text, 'MultiPolygon'::text]))) or ((feature_kind = 'walking_path'::text) and ((geometry_geojson ->> 'type'::text) = 'LineString'::text))))),
    constraint campus_map_features_height_check check (((height_metres >= (0)::double precision) and (minimum_height_metres >= (0)::double precision) and (minimum_height_metres <= height_metres))),
    constraint campus_map_features_kind_check check ((feature_kind = any (array['building'::text, 'walking_path'::text]))),
    constraint campus_map_features_name_not_blank_check check ((btrim(name) <> ''::text)),
    constraint campus_map_features_slug_format_check check ((slug ~ '^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$'::text)),
    constraint campus_map_features_sort_order_check check ((sort_order >= 0)),
    constraint campus_map_features_source_identifier_not_blank_check check ((btrim(source_identifier) <> ''::text)),
    constraint campus_map_features_source_license_not_blank_check check ((btrim(source_license) <> ''::text)),
    constraint campus_map_features_source_properties_check check ((jsonb_typeof(source_properties) = 'object'::text)),
    constraint campus_map_features_source_url_check check ((source_url ~ '^https://'::text)),
    constraint campus_map_features_status_check check ((status = any (array['draft'::text, 'published'::text, 'archived'::text])))
);

create table if not exists public.campus_map_layers (
    id uuid default gen_random_uuid() not null,
    slug text not null,
    name text not null,
    description text,
    colour text default '#52525b'::text not null,
    is_visible_by_default boolean default true not null,
    status text default 'draft'::text not null,
    sort_order integer default 0 not null,
    created_at timestamp with time zone default now() not null,
    updated_at timestamp with time zone default now() not null,
    campus_id uuid not null,
    layer_kind text default 'place'::text not null,
    style_layer_patterns text[] default '{}'::text[] not null,
    constraint campus_map_layers_colour_format_check check ((colour ~ '^#[0-9a-fA-F]{6}$'::text)),
    constraint campus_map_layers_description_not_blank_check check (((description is null) or (btrim(description) <> ''::text))),
    constraint campus_map_layers_kind_check check ((layer_kind = any (array['map'::text, 'place'::text, 'hybrid'::text]))),
    constraint campus_map_layers_name_not_blank_check check ((btrim(name) <> ''::text)),
    constraint campus_map_layers_slug_format_check check ((slug ~ '^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$'::text)),
    constraint campus_map_layers_sort_order_check check ((sort_order >= 0)),
    constraint campus_map_layers_status_check check ((status = any (array['draft'::text, 'published'::text, 'archived'::text]))),
    constraint campus_map_layers_style_patterns_check check (((array_position(style_layer_patterns, null::text) is null) and (array_position(style_layer_patterns, ''::text) is null)))
);

create table if not exists public.campus_map_place_details (
    id uuid default gen_random_uuid() not null,
    place_id uuid not null,
    kind text default 'place'::text not null,
    label text not null,
    sort_order integer default 0 not null,
    created_at timestamp with time zone default now() not null,
    updated_at timestamp with time zone default now() not null,
    constraint campus_map_place_details_kind_format_check check ((kind ~ '^[a-z][a-z0-9_]*$'::text)),
    constraint campus_map_place_details_label_not_blank_check check ((btrim(label) <> ''::text)),
    constraint campus_map_place_details_sort_order_check check ((sort_order >= 0))
);

create table if not exists public.campus_map_places (
    id uuid default gen_random_uuid() not null,
    layer_id uuid not null,
    slug text not null,
    name text not null,
    marker_label text not null,
    address text not null,
    longitude double precision not null,
    latitude double precision not null,
    official_url text,
    data_status text default 'example'::text not null,
    is_routable boolean default true not null,
    status text default 'draft'::text not null,
    sort_order integer default 0 not null,
    created_at timestamp with time zone default now() not null,
    updated_at timestamp with time zone default now() not null,
    map_display_kind text default 'point'::text not null,
    search_terms text[] default '{}'::text[] not null,
    source_provider text,
    source_identifier text,
    source_url text,
    source_license text,
    source_version bigint,
    source_updated_at timestamp with time zone,
    constraint campus_map_places_address_not_blank_check check ((btrim(address) <> ''::text)),
    constraint campus_map_places_data_status_check check ((data_status = any (array['example'::text, 'mapped'::text, 'verified'::text]))),
    constraint campus_map_places_display_kind_check check ((map_display_kind = any (array['building'::text, 'point'::text]))),
    constraint campus_map_places_latitude_check check (((latitude >= ('-90'::integer)::double precision) and (latitude <= (90)::double precision))),
    constraint campus_map_places_longitude_check check (((longitude >= ('-180'::integer)::double precision) and (longitude <= (180)::double precision))),
    constraint campus_map_places_marker_label_check check (((btrim(marker_label) <> ''::text) and (char_length(marker_label) <= 4))),
    constraint campus_map_places_name_not_blank_check check ((btrim(name) <> ''::text)),
    constraint campus_map_places_official_url_check check (((official_url is null) or (official_url ~ '^https://'::text))),
    constraint campus_map_places_slug_format_check check ((slug ~ '^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$'::text)),
    constraint campus_map_places_sort_order_check check ((sort_order >= 0)),
    constraint campus_map_places_source_check check ((((source_provider is null) and (source_identifier is null) and (source_url is null) and (source_license is null) and (source_version is null) and (source_updated_at is null)) or ((source_provider is not null) and (source_identifier is not null) and (source_url is not null) and (source_license is not null) and (btrim(source_provider) <> ''::text) and (btrim(source_identifier) <> ''::text) and (source_url ~ '^https://'::text) and (btrim(source_license) <> ''::text) and ((source_version is null) or (source_version > 0))))),
    constraint campus_map_places_status_check check ((status = any (array['draft'::text, 'published'::text, 'archived'::text])))
);

