create policy campus_indoor_maps_admin_delete on public.campus_indoor_maps for delete to authenticated using (( select private.has_permission('rooms.manage'::text) as has_permission));

create policy campus_indoor_maps_admin_insert on public.campus_indoor_maps for insert to authenticated with check (( select private.has_permission('rooms.manage'::text) as has_permission));

create policy campus_indoor_maps_admin_update on public.campus_indoor_maps for update to authenticated using (( select private.has_permission('rooms.manage'::text) as has_permission)) with check (( select private.has_permission('rooms.manage'::text) as has_permission));

create policy campus_indoor_maps_read_authenticated on public.campus_indoor_maps for select to authenticated using ((((status = 'published'::text) and (exists ( select 1
   from (public.campus_map_places places
     join public.campus_map_layers layers on ((layers.id = places.layer_id)))
  where ((places.id = campus_indoor_maps.building_place_id) and (places.status = 'published'::text) and (layers.status = 'published'::text))))) or ( select private.has_permission('rooms.manage'::text) as has_permission)));

create policy campus_indoor_maps_read_published on public.campus_indoor_maps for select to anon using (((status = 'published'::text) and (exists ( select 1
   from (public.campus_map_places places
     join public.campus_map_layers layers on ((layers.id = places.layer_id)))
  where ((places.id = campus_indoor_maps.building_place_id) and (places.status = 'published'::text) and (layers.status = 'published'::text))))));

