create policy campus_map_campuses_read_authenticated on public.campus_map_campuses for select to authenticated using (((status = 'published'::text) or ( select private.has_permission('rooms.manage'::text) as has_permission)));

create policy campus_map_campuses_read_published on public.campus_map_campuses for select to anon using ((status = 'published'::text));

