comment on table public.campus_indoor_maps is 'Versioned indoor floor-plan, connector and routing documents for Room Finder buildings.';

comment on table public.campus_map_campuses is 'Published campus boundaries and camera constraints for Room Finder.';

comment on table public.campus_map_features is 'ANU-scoped building polygons and walking lines with source provenance.';

comment on table public.campus_map_layers is 'Published Room Finder layers with database-managed display settings.';

comment on table public.campus_map_place_details is 'Ordered room, facility and service details belonging to a campus place.';

comment on table public.campus_map_places is 'Searchable Room Finder places, including the mapped ANU Acton building directory.';

comment on column public.campus_indoor_maps.document is 'Coursemap indoor document (version 2): levels, walls with openings, spaces, connectors and an explicit route graph in local units at ten units per metre.';

comment on column public.campus_map_features.height_metres is 'Safe display height for the ANU-only building extrusion.';

comment on column public.campus_map_features.source_properties is 'Selected source tags retained for provenance and future map refinements.';

comment on column public.campus_map_layers.layer_kind is 'Controls whether a layer filters map vectors, place markers or both.';

comment on column public.campus_map_layers.style_layer_patterns is 'Ordered MapLibre style layer globs. Prefix a glob with ! to exclude it from the group.';

comment on column public.campus_map_places.map_display_kind is 'Selects whether a place resolves to a live building footprint or remains a non-building point.';

comment on column public.campus_map_places.search_terms is 'Normalised aliases and source identifiers included in Room Finder search.';

comment on column public.campus_map_places.source_identifier is 'Stable identifier from the external source used to update mapped places.';

-- ANU Acton as imported from OpenStreetMap: the campus, its map layers, and
-- the places and vector features drawn on them. This is reference data, not
-- a fixture, so it ships with the schema rather than with the preview seed.

-- Every object is taken back to nothing before it is granted anything, so the
-- grants below are the whole of what each role holds rather than an addition
-- to whatever Supabase's defaults already handed out.

revoke all on table public.campus_indoor_maps from public, anon, authenticated, service_role;

revoke all on table public.campus_map_campuses from public, anon, authenticated, service_role;

revoke all on table public.campus_map_features from public, anon, authenticated, service_role;

revoke all on table public.campus_map_layers from public, anon, authenticated, service_role;

revoke all on table public.campus_map_place_details from public, anon, authenticated, service_role;

revoke all on table public.campus_map_places from public, anon, authenticated, service_role;

grant all on table public.campus_indoor_maps to service_role;

grant select on table public.campus_indoor_maps to anon;

grant select,insert,delete,update on table public.campus_indoor_maps to authenticated;

grant all on table public.campus_map_campuses to service_role;

grant select on table public.campus_map_campuses to anon;

grant select,insert,delete,update on table public.campus_map_campuses to authenticated;

grant all on table public.campus_map_features to service_role;

grant select on table public.campus_map_features to anon;

grant select,insert,delete,update on table public.campus_map_features to authenticated;

grant all on table public.campus_map_layers to service_role;

grant select on table public.campus_map_layers to anon;

grant select,insert,delete,update on table public.campus_map_layers to authenticated;

grant all on table public.campus_map_place_details to service_role;

grant select on table public.campus_map_place_details to anon;

grant select,insert,delete,update on table public.campus_map_place_details to authenticated;

grant all on table public.campus_map_places to service_role;

grant select on table public.campus_map_places to anon;

grant select,insert,delete,update on table public.campus_map_places to authenticated;
